for url in ['https://www.nature.com/articles/s41467-021-22627-w','https://pmc.ncbi.nlm.nih.gov/articles/PMC11109505/']:
    try:
        data=urllib.request.urlopen(url, timeout=20).read().decode('utf-8','ignore')
        print('URL',url,'len',len(data))
        for pat in ['citation_pmid" content="([0-9]+)','"pmid":"([0-9]+)','PMID:?\s*([0-9]{6,})','pubmed/([0-9]+)']:
            print(pat, sorted(set(re.findall(pat,data)))[:10])
        for pat in ['citation_doi" content="([^"]+)','doi.org/([^"<> ]+)']:
            print(pat, sorted(set(re.findall(pat,data)))[:5])
    except Exception as e:
        print('ERR',url,e)
