python - <<'PY'
import urllib.request, re
for url in ['https://www.nature.com/articles/s41467-021-22627-w','https://pmc.ncbi.nlm.nih.gov/articles/PMC11109505/']:
    try:
        data=urllib.request.urlopen(url, timeout=20).read().decode('utf-8','ignore')
        print('URL',url,'len',len(data))
        for pat in ['citation_pmid" content="([0-9]+)','"pmid":"([0-9]+)','PMID:?\s*([0-9]{6,})','pubmed/([0-9]+)']:
            print(pat, sorted(set(re.findall(pat,data)))[:10])
        for pat in ['citation_doi" content="([^"]+)','doi.org/([^"<> ]+)']:
            print(pat, sorted(set(re.findall(pat,data)))[:5])
    except Exception as e:
        print('ERR',url,e)
PY

python - <<'PY'
import urllib.request, json, re
urls=[
 'https://api.crossref.org/works/10.1038/s41467-021-22627-w',
 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?db=pubmed&term=10.1038/s41467-021-22627-w[DOI]&retmode=json'
]
for url in urls:
  try:
    d=urllib.request.urlopen(url, timeout=20).read().decode()
    print(url); print(d[:1000])
  except Exception as e: print('ERR',e)
PY

python - <<'PY'
import urllib.request, re
for url in ['https://www.nature.com/articles/s41467-021-22627-w','https://pmc.ncbi.nlm.nih.gov/articles/PMC11109505/']:
    html=urllib.request.urlopen(url, timeout=20).read().decode('utf-8','ignore')
    print('\n',url)
    for phrase in ['GEMIN5-related neurodevelopmental disorders','GEMIN5 disorders','GEMIN5-related neurodevelopmental disorder','GEMIN5 disorder']:
        print(phrase, phrase.lower() in html.lower())
    for m in re.finditer(r'.{0,80}GEMIN5.{0,80}', html, flags=re.I):
        s=re.sub('<[^>]+>',' ',m.group(0));
        if 'disorder' in s.lower() or 'neurodevelopment' in s.lower(): print(s[:300])
PY

